737: void CIPAddress::pton(sockaddr* addr, const uint32_t ip[4], int ver)
738: {
739:    if (AF_INET == ver)
740:    {
741:       sockaddr_in* a = (sockaddr_in*)addr;
742:       a->sin_addr.s_addr = ip[0];
743:    }
744:    else
745:    {
746:       sockaddr_in6* a = (sockaddr_in6*)addr;
747:       for (int i = 0; i < 4; ++ i)
