111: class CRcvLossList
112: {
113: public:
114:    CRcvLossList(int size = 1024);
115:    ~CRcvLossList();
116: 
117:       // Functionality:
118:       //    Insert a series of loss seq. no. between "seqno1" and "seqno2" into the receiver's loss list.
119:       // Parameters:
120:       //    0) [in] seqno1: sequence number starts.
121:       //    1) [in] seqno2: seqeunce number ends.
122:       // Returned value:
123:       //    None.
124: 
125:    void insert(int32_t seqno1, int32_t seqno2);
126: 
127:       // Functionality:
128:       //    Remove a loss seq. no. from the receiver's loss list.
129:       // Parameters:
130:       //    0) [in] seqno: sequence number.
131:       // Returned value:
132:       //    if the packet is removed (true) or no such lost packet is found (false).
133: 
134:    bool remove(int32_t seqno);
135: 
136:       // Functionality:
137:       //    Remove all packets between seqno1 and seqno2.
138:       // Parameters:
139:       //    0) [in] seqno1: start sequence number.
140:       //    1) [in] seqno2: end sequence number.
141:       // Returned value:
